import{_ as a,c as o,o as n,a3 as s}from"./chunks/framework.CoV49S2T.js";const m=JSON.parse('{"title":"Preguntas frecuentes","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/faq.md","filePath":"es/guide/faq.md","lastUpdated":1786597585000}'),r={name:"es/guide/faq.md"};function t(i,e,p,l,c,d){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h1><p><strong>P: ¿Qué es ClipboardxAI?</strong></p><p>R: ClipboardxAI es un gestor de portapapeles inteligente para macOS. Mantiene un historial buscable de todo lo que copia y le permite ejecutar acciones sobre él — resumir, traducir, ordenar texto o enviarlo a un modelo de IA en la nube.</p><p><strong>P: ¿Qué versiones de macOS son compatibles?</strong></p><p>R: macOS 14 Sonoma o posterior, optimizado para Apple Silicon (serie M) con compatibilidad para Intel.</p><p><strong>P: ¿Cómo lo instalo?</strong></p><p>R: Descárguelo desde la <a href="/es/">Mac App Store</a> (recomendado) o obtenga la última compilación desde <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a>. Consulte la <a href="/es/guide/installation.html">Guía de instalación</a>.</p><p><strong>P: ¿Es gratuito ClipboardxAI?</strong></p><p>R: ClipboardxAI es una app de pago en el Mac App Store. Tras la compra, todas las herramientas locales integradas están incluidas y no se requiere cuenta. Las acciones de IA en la nube usan la API key de <em>su propio</em> proveedor, por lo que solo paga al proveedor de IA directamente — no hay ninguna capa de pago adicional en la aplicación.</p><p><strong>P: ¿Qué proveedores de IA son compatibles?</strong></p><p>R: Cualquier proveedor compatible con OpenAI: DeepSeek, MiniMax, Zhipu GLM, Kimi (Moonshot), Mistral y el Ollama local — además de OpenAI, Anthropic y Gemini. Su clave se almacena en el Keychain.</p><p><strong>P: ¿Funciona sin conexión?</strong></p><p>R: Sí. El historial del portapapeles y las herramientas locales integradas (extraer enlaces, contar estadísticas, colapsar líneas en blanco y más) se ejecutan completamente en su Mac sin conexión a internet.</p><p><strong>P: ¿Son privados mis datos del portapapeles?</strong></p><p>R: Su historial permanece en su dispositivo. La IA en la nube es opcional y envía el contenido solo al proveedor que configure, usando una clave de su Keychain. Nunca recibimos ni almacenamos sus fragmentos, y no hay telemetría. Consulte la <a href="/es/guide/privacy.html">Política de privacidad</a>.</p><p><strong>P: ¿Cómo añado más acciones?</strong></p><p>R: Explore el <a href="/es/marketplace/">Marketplace</a> y haga clic en <strong>Instalar</strong> en cualquier acción. Abre la aplicación mediante un enlace profundo y aparece en su lista de <strong>Instaladas</strong>.</p><p><strong>P: ¿Cómo actualizo la aplicación?</strong></p><p>R: La versión de la Mac App Store se actualiza automáticamente. Para las compilaciones de GitHub, descargue la última versión y reemplace la aplicación en <code>Applications</code>.</p><p><strong>P: ¿Cómo informo de errores o solicito funciones?</strong></p><p>R: Abra un issue en el <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">repositorio de GitHub</a>. Incluya su versión de macOS, la versión de la aplicación y los pasos para reproducirlo.</p><p><strong>P: ¿Dónde se almacenan mis datos?</strong></p><p>R: En el contenedor sandbox:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.clipboard/Data/Library/Application Support/com.w3cub.clipboard/</span></span></code></pre></div><p>Las API keys residen en el Keychain del sistema, no en esa carpeta.</p>',25)])])}const g=a(r,[["render",t]]);export{m as __pageData,g as default};
